{
  "appearance_facts": [
    {
      "location": "Chart area",
      "fact": "There are six blue circular data points arranged horizontally across the chart, one for each category on the x-axis."
    },
    {
      "location": "Service Design category (center-left)",
      "fact": "The data point for Service Design is the lowest of all six points on the page, positioned vertically between the 20 and 25 grid lines."
    },
    {
      "location": "Service Quality category (far left)",
      "fact": "The data point for Service Quality is the highest of all six points on the page, positioned vertically near the 60 grid line."
    },
    {
      "location": "Other category (far right)",
      "fact": "The data point for Other is the second highest on the page, positioned slightly below the Service Quality point."
    },
    {
      "location": "Service Delivery category (center-right)",
      "fact": "The data point for Service Delivery is positioned vertically between the 35 and 40 grid lines, lower than the Service Quality, Other, and Support Access points."
    },
    {
      "location": "All categories",
      "fact": "All data points are the same size and color (blue with a dark outline)."
    }
  ],
  "printed_facts": [
    {
      "location": "Chart Title",
      "fact": "Public Service Feedback Share by Category"
    },
    {
      "location": "Y-Axis",
      "fact": "Labelled 'Value' with a scale from 0 to 65 in increments of 5."
    },
    {
      "location": "X-Axis",
      "fact": "Labelled 'Feedback Category' with tick labels: Service Quality, Service Cost, Service Design, Support Access, Service Delivery, Other."
    },
    {
      "location": "Data Labels",
      "fact": "Percentage values are printed above each point: 41% (Service Quality), 46% (Service Cost), 51% (Service Design), 42% (Support Access), 36% (Service Delivery), 10% (Other)."
    }
  ],
  "public_definitions": [
    "Routing criterion: Highest feedback share in the dashboard"
  ],
  "uncertain": [
    "There is a visual conflict between the vertical position of the points (where Service Quality is highest) and the printed percentage labels (where Service Design is highest at 51%). It is unclear which visual channel represents the 'share' intended for the routing decision."
  ]
}
